import { Asset } from "expo-asset";
import { File } from "expo-file-system";
import libraryAsset from "../../assets/synth/spessasynth.bundle.txt";
import processorAsset from "../../assets/synth/spessasynth_processor.txt";

export interface SynthSources {
  libraryJs: string;
  processorJs: string;
}

async function readAssetText(moduleId: number): Promise<string> {
  const asset = Asset.fromModule(moduleId);
  await asset.downloadAsync();
  return new File(asset.localUri ?? asset.uri).text();
}

/** Reads the bundled SpessaSynth sources (generated by `npm run build:synth`). */
export async function loadSynthSources(): Promise<SynthSources> {
  const [libraryJs, processorJs] = await Promise.all([
    readAssetText(libraryAsset),
    readAssetText(processorAsset),
  ]);
  return { libraryJs, processorJs };
}
